// ─── File: KvScaleDemo.java ───
// Runnable demo: partition + route + replicate + hot-key cache + node-failure survival.
package com.bank.kvscale;

import java.util.*;
import java.util.logging.*;

public class KvScaleDemo {

    private static final Logger log = Logger.getLogger("KvScale");

    static {
        Logger root = Logger.getLogger("");
        for (var h : root.getHandlers()) root.removeHandler(h);
        ConsoleHandler handler = new ConsoleHandler();
        handler.setFormatter(new BankLogFormatter());
        handler.setLevel(Level.ALL);
        log.setUseParentHandlers(false);
        log.addHandler(handler);
        log.setLevel(Level.ALL);
    }

    public static void main(String[] args) {
        // Capacity planning: how many nodes for 1M rps?
        int targetRps = 1_000_000, perNode = 100_000, rf = 3; double headroom = 1.5;
        int nodes = (int) Math.ceil((double) targetRps / perNode * headroom);
        int withReplicas = nodes * rf / rf;   // throughput nodes; data copied RF times
        log.info(() -> "capacity plan: " + targetRps + " rps / " + perNode
                + " per node * " + headroom + " headroom = " + nodes + " nodes (RF=" + rf + ")");

        // Build cluster: consistent-hash ring, RF=3, quorum R=2/W=2.
        KvCluster cluster = new KvCluster(6, 150, 3, 2, 2);
        cluster.put("SAV2001", "balance=1000000");
        cluster.put("CUR3001", "balance=250000");
        log.info(() -> "quorum read SAV2001 = " + cluster.get("SAV2001"));

        // Node failure: the node owning SAV2001 dies → replica still serves it.
        cluster.failPrimaryOf("SAV2001");
        log.warning("primary of SAV2001 failed → serving from a replica (RF=3)");
        log.info(() -> "after failure, read SAV2001 = " + cluster.get("SAV2001")
                + "  ← available via replica; load redistributes to peers");

        // Hot key: a merchant account hammered with reads → cache absorbs them.
        HotKeyCache cache = new HotKeyCache(cluster, 50_000);
        cluster.put("MERCHANT9", "balance=500000000");
        int backendHits = 0;
        for (int i = 0; i < 100_000; i++) if (cache.get("MERCHANT9")) backendHits++;
        final int hits = backendHits;
        log.info(() -> "hot key MERCHANT9: 100000 reads → only " + hits
                + " reached backend (cache + per-key rate limit absorbed the rest)");
    }
}

// ─── ring/ConsistentHashRing.java (partitioning: ring + virtual nodes) ───
class ConsistentHashRing {
    private final int vnodes;
    private final TreeMap<Integer, String> ring = new TreeMap<>();
    ConsistentHashRing(int vnodes) { this.vnodes = vnodes; }
    void addNode(String node) {
        for (int v = 0; v < vnodes; v++) ring.put(hash(node + "#" + v), node);
    }
    void removeNode(String node) { ring.values().removeIf(n -> n.equals(node)); }
    // Primary + next (RF-1) distinct nodes clockwise = replica set for a key.
    List<String> replicasFor(String key, int rf) {
        List<String> result = new ArrayList<>();
        if (ring.isEmpty()) return result;
        int h = hash(key);
        for (Map.Entry<Integer, String> e :
                ring.tailMap(h, true).entrySet()) addDistinct(result, e.getValue(), rf);
        for (Map.Entry<Integer, String> e : ring.entrySet()) addDistinct(result, e.getValue(), rf);
        return result;
    }
    private void addDistinct(List<String> out, String n, int rf) {
        if (out.size() < rf && !out.contains(n)) out.add(n);
    }
    private int hash(String s) { return s.hashCode() & 0x7fffffff; }
}

// ─── cluster/KvNode.java (one storage node) ───
class KvNode {
    final String id; boolean alive = true;
    final Map<String, String> store = new HashMap<>();
    KvNode(String id) { this.id = id; }
}

// ─── cluster/KvCluster.java (replication + quorum read/write + failure handling) ───
class KvCluster {
    private static final Logger log = Logger.getLogger("KvScale");
    private final ConsistentHashRing ring = new ConsistentHashRing(150);
    private final Map<String, KvNode> nodes = new HashMap<>();
    private final int rf, readQuorum, writeQuorum;
    KvCluster(int n, int vnodes, int rf, int r, int w) {
        this.rf = rf; this.readQuorum = r; this.writeQuorum = w;
        for (int i = 0; i < n; i++) { KvNode node = new KvNode("node" + i);
            nodes.put(node.id, node); ring.addNode(node.id); }
    }
    void put(String key, String value) {
        int acks = 0;
        for (String id : ring.replicasFor(key, rf)) {
            KvNode node = nodes.get(id);
            if (node.alive) { node.store.put(key, value); acks++; }   // write to replicas
        }
        if (acks < writeQuorum) throw new RuntimeException("write quorum not met");
    }
    String get(String key) {
        int reads = 0; String value = null;
        for (String id : ring.replicasFor(key, rf)) {
            KvNode node = nodes.get(id);
            if (node.alive && node.store.containsKey(key)) { value = node.store.get(key); reads++; }
            if (reads >= readQuorum) break;                           // quorum read
        }
        return value;
    }
    void failPrimaryOf(String key) {
        String primary = ring.replicasFor(key, rf).get(0);
        nodes.get(primary).alive = false;   // routing/gossip would mark it down fleet-wide
    }
}

// ─── cache/HotKeyCache.java (absorb skewed reads + per-key rate limit) ───
class HotKeyCache {
    private final KvCluster backend; private final int rateLimit;
    private final Map<String, String> cache = new HashMap<>();
    private int perKeyCount = 0;
    HotKeyCache(KvCluster backend, int rateLimit) { this.backend = backend; this.rateLimit = rateLimit; }
    // return true if the read reached the backend (cache miss within rate limit)
    boolean get(String key) {
        if (cache.containsKey(key)) return false;        // cache hit → backend untouched
        if (perKeyCount++ < rateLimit) { cache.put(key, backend.get(key)); return true; }
        return false;                                    // rate-limited → shed load off backend
    }
}

class BankLogFormatter extends Formatter {
    @Override public String format(LogRecord r) {
        return String.format("%1$tF %1$tT %2$-7s %3$s%n",
                new java.util.Date(r.getMillis()), r.getLevel(), r.getMessage());
    }
}
